using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Reflection;namespace ServiceTool{internal static class SettingsSpacingTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);int n=0;foreach(bool dark in new[]{true,false})using(var f=new InitialSystemSettingsForm(true)){f.SetTheme(dark,false);f.Show();for(int i=0;i<15;i++)Application.DoEvents();var g=Walk(f).OfType<ServiceGrid>().Single();foreach(DataGridViewRow r in g.Rows)r.Cells[2].Value="Политики BARS применены; Подробности в журнале";g.Rows[2].Cells[2].Value="Доменный: отключено; Частный: отключено; Общедоступный: отключено";for(int i=0;i<20;i++)Application.DoEvents();if(g.Columns[2].DefaultCellStyle.WrapMode!=DataGridViewTriState.True)throw new Exception("Status wrap disabled");n++;var buttons=Walk(f).OfType<BrandButton>().Where(b=>b.Text=="Проверить настройки"||b.Text=="Применить политики"||b.Text=="Вернуть стандартные политики").ToArray();var refresh=buttons.Single(b=>b.Text=="Проверить настройки");var journal=Walk(f).OfType<JournalTextBox>().Single();int top=g.PointToScreen(new Point(0,g.Height)).Y;int buttonTop=refresh.PointToScreen(Point.Empty).Y;int bottom=refresh.PointToScreen(new Point(0,refresh.Height)).Y;int logTop=journal.Parent.Parent.PointToScreen(Point.Empty).Y;if(Math.Abs((buttonTop-top)-(logTop-bottom))>1)throw new Exception("Unequal visible gaps");n++;Console.WriteLine("Gaps: table/buttons="+(buttonTop-top)+", buttons/journal="+(logTop-bottom));using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings-"+dark+".png"));}n++;}Console.WriteLine("PASS: "+n+" preview checks; no settings applied.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}